   if(!frame.isFinished())throw new AssertionError("Strict trace incomplete");equal(1,seen,"one executed return boundary");equal(0L,reg(state,"A1"),"internal loop completed");equal(0x22334455L,memory(state,0x8000),"first final store");equal(0x11223344L,memory(state,0x8004),"second final store");equal(18L,reg(state,"B4"),"caller ADDAD");equal(n(r,"caller_end"),reg(state,"PC"),"strict bounded exit");equal(Set.of("B4"),trace.outgoingE1Writes(),"outgoing caller hazard");r.addProperty("cycles",cycles);r.addProperty("states",schedule.states());records.add(r);
